<?php
admin_open('sirkulasi');
$active=q("SELECT l.*,m.nama,b.judul,i.barcode FROM loan l JOIN member m ON m.id=l.member_id JOIN item i ON i.id=l.item_id JOIN biblio b ON b.id=i.biblio_id WHERE l.tgl_kembali IS NULL ORDER BY l.jatuh_tempo")->fetchAll();
$available=q("SELECT i.id,i.barcode,b.judul FROM item i JOIN biblio b ON b.id=i.biblio_id WHERE NOT EXISTS(SELECT 1 FROM loan l WHERE l.item_id=i.id AND l.tgl_kembali IS NULL) ORDER BY b.judul")->fetchAll();
$members=q('SELECT * FROM member ORDER BY nama')->fetchAll();
echo "<h1>Sirkulasi</h1>$fl<div class='two'><div class='pn'><h3>Catat peminjaman</h3><small>Isi data peminjam dan eksemplar buku.</small>";
if($available && $members){echo "<form class='fm' method='post' action='?act=pinjam' style='margin-top:16px'><div class='w'><label>Anggota</label><select name='member' required>";foreach($members as $m)echo "<option value='{$m['id']}'>".h($m['nama'])." — ".h($m['kelas'])."</option>";echo "</select></div><div class='w'><label>Eksemplar buku</label><select name='item' required>";foreach($available as $i)echo "<option value='{$i['id']}'>".h($i['judul'])." (".h($i['barcode']).")</option>";echo "</select></div><div class='w'><label>Lama peminjaman (hari)</label><input type='number' name='hari' min='1' max='30' value='7' required></div><div class='w' style='margin-top:18px'><button class='btn'>＋ Simpan Peminjaman</button></div></form>";}else echo "<p style='margin-top:16px;color:var(--mut)'>Pastikan sudah ada anggota dan eksemplar buku yang tersedia.</p>";
echo "</div><div class='pn'><h3>Ringkasan</h3><div class='stats' style='grid-template-columns:1fr 1fr;margin-top:16px'><div class='st'><span>Sedang dipinjam</span><b>".count($active)."</b></div><div class='st'><span>Eksemplar tersedia</span><b>".count($available)."</b></div></div><a class='btn g' href='?page=notifikasi'>Lihat pengingat →</a></div></div>";
echo "<div class='pn'><div class='top'><h3>Peminjaman aktif</h3><span class='pill'>".count($active)." transaksi</span></div><table><tr><th>Anggota</th><th>Judul</th><th>Tanggal pinjam</th><th>Jatuh tempo</th><th>Status</th><th>Aksi</th></tr>";
foreach($active as $l){$days=overdueDays($l['jatuh_tempo']);$status=$days>0?"<span class='bd b2'>Terlambat $days hari</span>":($l['jatuh_tempo']===date('Y-m-d')?"<span class='bd b1'>Jatuh tempo hari ini</span>":"<span class='bd b3'>Dipinjam</span>");echo "<tr><td>".h($l['nama'])."</td><td>".h($l['judul'])."</td><td>".h($l['tgl_pinjam'])."</td><td>".h($l['jatuh_tempo'])."</td><td>$status</td><td><form method='post' action='?act=kembali' onsubmit=\"return confirm('Catat pengembalian buku ini?')\"><input type='hidden' name='id' value='{$l['id']}'><button class='btn s g'>Kembalikan</button></form></td></tr>";}
if(!$active)echo "<tr><td colspan='6'>Belum ada peminjaman aktif.</td></tr>";
echo '</table></div>';admin_close();
